-- Agriculture uses the existing photo, stock, variant, delivery and pickup workflows.
insert into store_categories(name,slug,description,icon,sort_order,features,attributes,workflow,is_active)
values ($$Agriculture & Livestock$$,$$agriculture-livestock$$,$$Crayfish, catfish, poultry, eggs, livestock and fresh or processed farm produce.$$,$$sprout$$,16,
'{"catalogue":true,"cart":true,"stock":true,"delivery":true,"pickup":true,"variants":true,"reviews":true}'::jsonb,
'[{"key":"produce_type","label":"Produce type","type":"select","required":true,"options":["Crayfish & seafood","Catfish & other fish","Chicken & other poultry","Eggs","Livestock","Vegetables & fruits","Grains, tubers & legumes","Other farm produce"]},{"key":"sale_unit","label":"Price is per","type":"select","required":true,"options":["Kilogram (kg)","Gram (g)","Litre","Piece","Bird / animal","Crate","Basket","Bag","Bunch","Pack","Other (describe pack size)"]},{"key":"pack_size","label":"Exact weight / pack size (e.g. 1 kg, 30 eggs, 50 kg bag)","type":"text","required":true},{"key":"minimum_order","label":"Minimum order (number of selling units)","type":"number","required":true},{"key":"produce_condition","label":"Condition / processing","type":"select","required":true,"options":["Live","Fresh / raw","Chilled","Frozen","Dried","Smoked","Processed / packaged"]},{"key":"source_location","label":"Farm / source location (town and LGA)","type":"text","required":true},{"key":"storage_instructions","label":"Storage and shelf-life instructions","type":"textarea","required":true},{"key":"fulfilment_notes","label":"Pickup / delivery timing, packaging and handling","type":"textarea","required":true},{"key":"harvest_date","label":"Harvest / catch / processing date (YYYY-MM-DD, if applicable)","type":"text"},{"key":"breed_variety","label":"Breed / species / variety","type":"text"},{"key":"animal_age","label":"Age and typical live weight (include units)","type":"text"},{"key":"health_details","label":"Live animal health, vaccination and treatment details","type":"textarea"},{"key":"egg_details","label":"Egg size / grade and collection date (YYYY-MM-DD)","type":"text"},{"key":"fish_preparation","label":"Fish / seafood size, cleaning and processing details","type":"textarea"}]'::jsonb,'[]'::jsonb,true)
on conflict(slug) do update set name=excluded.name,description=excluded.description,features=excluded.features,attributes=excluded.attributes,icon=excluded.icon,is_active=true;
